public class QExcDemo {public static void main(String[] args){ICharQ q=new FixedQueue(2);try{q.put('A');q.put('Б');try{q.put('В');}catch(QueueFullException e){System.out.println("Обработано переполнение");}System.out.println(q.get());System.out.println(q.get());try{q.get();}catch(QueueEmptyException e){System.out.println("Обработана пустота");}}catch(QueueFullException|QueueEmptyException e){throw new AssertionError(e);}}}
